    10→fn test_power_zones_from_ftp_200() {
    11→    let zones = PowerZones::from_ftp(200);
    12→
    13→    // Verify zone boundaries
    14→    // Z1: 0-55% = 0-110W
    15→    assert_eq!(zones.z1_recovery.min_watts, 0);
    16→    assert_eq!(zones.z1_recovery.max_watts, 110);
    17→    assert_eq!(zones.z1_recovery.zone, 1);
    18→
    19→    // Z2: 56-75% = 112-150W
    20→    assert_eq!(zones.z2_endurance.min_watts, 112);
    21→    assert_eq!(zones.z2_endurance.max_watts, 150);
    22→    assert_eq!(zones.z2_endurance.zone, 2);
    23→
    24→    // Z3: 76-90% = 152-180W
    25→    assert_eq!(zones.z3_tempo.min_watts, 152);
    26→    assert_eq!(zones.z3_tempo.max_watts, 180);
    27→
    28→    // Z4: 91-105% = 182-210W (threshold = FTP)
    29→    assert_eq!(zones.z4_threshold.min_watts, 182);
    30→    assert_eq!(zones.z4_threshold.max_watts, 210);
    31→
    32→    // Z5: 106-120% = 212-240W
    33→    assert_eq!(zones.z5_vo2max.min_watts, 212);
    34→    assert_eq!(zones.z5_vo2max.max_watts, 240);
    35→
    36→    // Z6: 121-150% = 242-300W
    37→    assert_eq!(zones.z6_anaerobic.min_watts, 242);
    38→    assert_eq!(zones.z6_anaerobic.max_watts, 300);
    39→
    40→    // Z7: >150% = >302W
    41→    assert_eq!(zones.z7_neuromuscular.min_watts, 302);
    42→}
